// 白日不是四个永远不变的资源按钮。每一日都把同一套办事动词落到不同的
// 人、物件与代价上；actor 是此刻会记住玩家选择的人，结果卡必须让她开口。
const pressureMove = (actor, label, hint, text) => Object.freeze({ actor, label, hint, text });
const pressureMoves = (ledger, office, listen, banquet) => Object.freeze({
  ledger: pressureMove(...ledger), office: pressureMove(...office),
  listen: pressureMove(...listen), banquet: pressureMove(...banquet),
});
const agenda = (id, dilemma, focus, actions) => Object.freeze({ id, dilemma, focus: Object.freeze(focus), actions });
const tradePreparation = (label, hint, text) => Object.freeze({ label, hint, text });
const preparedMove = (actor, preparation) => [actor, preparation.label, preparation.hint, preparation.text];

// 第四日白日只能算出价差、备好见证或听见待互证口风；娇儿是否交付一张可
