  listen:tradePreparation('听出报价口径','听见约低三成的原话；仍是待互证口风','金莲故意把票面报高，娇儿脱口说“少三成也嫌贵”，随即扣紧描金匣。金莲只记原话与时辰：“口径听见了，不等于她把能拿出去引用的底价纸卖给我们。”'),
  banquet:tradePreparation('列数、名、沉默三栏','写清三种报价各处分什么；精确底数栏保持空白','月娘把“买数、买名字、买沉默”分成三栏，请瓶儿核数、玉楼核见证、雪娥核谁承担跑腿。娇儿只确认三栏含义，没有填精确底数；这页是议价目录，不是成交凭据。'),
