// 联院差事曾经办成，不等于那套办法从此可以无价复制。外头拿着第二张契来
// 要求「照规矩办」时，两名原经手人要分别决定守住、收窄或撤回旧先例；裁决
// 只结算复制这次办法的真实成本，不补证链，也不增加联院差事完成数。
const precedentVoice = (line, reason) => Object.freeze({ line, reason });
const precedentPosition = (label, voices) => Object.freeze({ label, voices: Object.freeze(voices) });
const precedentRuling = (label, hint, body, effects, steps, result, bounded = null) => Object.freeze({
  label, hint, body, effects: Object.freeze(effects),
  settlement: Object.freeze({ steps: Object.freeze(steps), result }),
  bounded: bounded ? Object.freeze({ ...bounded, effects:Object.freeze(bounded.effects), steps:Object.freeze(bounded.steps) }) : null,
});
const portablePrecedent = (id, jointAction, participants, handler, object, request, positions, rulings) => {
  const outsider = Object.freeze({ ...handler, adult: true });
  const replies = Object.freeze(Object.fromEntries(participants.map((heroine) => [heroine, Object.freeze(Object.fromEntries(
    ['stand','narrow','withdraw'].map((stance) => {
      const voice = positions[stance].voices[heroine];
      return [stance, Object.freeze({ title:positions[stance].label, body:`${voice.line}${voice.reason}`, ...voice })];
    }),
  ))])));
  const choices = Object.freeze(Object.entries(rulings).map(([choiceId, ruling]) => Object.freeze({
    id:choiceId, label:ruling.label, hint:ruling.hint, text:ruling.body, effects:ruling.effects,
    effectsByScope:ruling.bounded ? Object.freeze({ bounded:ruling.bounded.effects }) : undefined,
  })));
  const scopeLabels = Object.freeze({
    honor_precedent:'完整携出，连成本与纠错权一并执行',
    named_exception:'具名限次，只为眼前契约执行',
    inside_only:'只留宅内，不授外部执行权',
  });
  const resolutions = Object.freeze(Object.fromEntries(Object.entries(rulings).map(([choiceId, ruling]) => {
    const standard = Object.freeze({ title:ruling.label, body:ruling.settlement.result, scopeLabel:scopeLabels[choiceId], steps:ruling.settlement.steps });
    if (!ruling.bounded) return [choiceId, standard];
    const bounded = Object.freeze({ title:ruling.bounded.title, body:ruling.bounded.result, scopeLabel:'只执行两人共同授权的窄界', steps:ruling.bounded.steps });
    return [choiceId, Object.freeze({ default:standard, bounded })];
  })));
  return Object.freeze({
    id, jointAction, participants: Object.freeze(participants), outsider, handler:outsider,
    title:'第二张照规矩来的契',
    opening:Object.freeze({ title:`${handler.name}带来${object.portable}`, body:request }),
    object: Object.freeze({ ...object, matchingMarks: Object.freeze(object.matchingMarks) }),
    request, replies, choices, resolutions,
    positions: Object.freeze(positions), rulings: Object.freeze(rulings),
    protectedState: Object.freeze(['resolvedPressures', 'jointActions']),
  });
};

