// 第五日决定一碗热汤怎样越过院门，第六日决定食盒、工钱与假账怎样互见；第七日的第一张
// 夜簿必须从这些仍在桌上的传菜底单起笔。三种前史只各有一个开场，Day 6 仅以
// 物件回声补入，不扩成二十七种组合；三个既有 choice id 与基础 effects 保持不变。
export const COUNCIL_7_HISTORY_VARIANTS = Object.freeze({
  follow_5_name_everyone:council7HistoryVariant(
    'follow_5_name_everyone','逐手传菜底单压在夜簿旁','五碗逐手传菜底单',
    '玳安送回那张由添火、提盒、春梅、门房逐手圈过的传菜底单。月娘把它压在空白夜簿旁：正式席序未改，今夜去处却仍会添饭食与守火。金莲先问原话是否只能由本人写、本人改，并在天亮后失效；瓶儿覆住私钥与私银栏，玉楼摊开撤菜签，雪娥把每一更添火与跑腿工名写到纸背。',{
      act_6_show_all:'第六日摊开的五处改字也在桌上；五人已经见过一张纸怎样拆成五份嫌疑，今晚任何共页都必须保留本人改字与核对痕迹。',
      act_6_each_copy:'第六日五院各领的抄本只以五色问签相接；今晚若留共页，也不能借夜簿取得任何一院未交出的原文。',
      act_6_feed_one:'第六日放出的假封签仍记着瓶儿的撤回时辰；今晚若写去处，任何一人叫停后都不得再拿旧行继续放话。',
    },[
      council7ChoiceText('council_7_tonight','只写今晚','本人只报今晚去处与是否留宿；只有本人能改，旧字保留，到明日卯初整页失效','五个人只把今晚愿意公开的院门与是否留宿各写一行。门房只能照字传，不能补猜；当事人可在落灯前亲手划改，旧字留痕，卯初以后任何人不得拿这页推定下一夜。'),
      council7ChoiceText('council_7_their_turn','各人写自己','每人只写自己的需要、答复与可转述范围；本人随时收回，散席即失效','你不排今晚。月娘、金莲、瓶儿、玉楼与雪娥各领一张窄签，只写本人愿意见谁、拒绝什么、准门房转述到哪里；任何改动仍由原落字者亲手完成，散席后五签不续作明日安排。'),
      council7ChoiceText('council_7_hide','不留去处副本','门房不记院名，只记谁传话、谁纠错；本人可改原话，去处栏从未生效','门房簿不落任何院名与留宿答案，只写传话人、送达时辰和纠错人。五个人各自保管原话，旁人不能代改；卯初封存责任页，旧传话不得被解释成下一夜的去处。'),
    ]),
  follow_5_let_them_edit:council7HistoryVariant(
    'follow_5_let_them_edit','家主认下的补工单围住空白簿','五院亲写饭食与补工原件',
    '第五日那张补工单仍留着五种不同笔迹：金莲让春梅只认一回，瓶儿写糖柴价，玉楼写外传版本，雪娥补回守火工，月娘只记正式席序未改。现在门房要添一张夜簿，五个人先把各自那一角压在纸边：谁的去处由谁写，谁能借它添差，旧同意何时作废，都不能再由一枚总印代答。',{
      act_6_show_all:'第六日五处改字已经共同摊验；今晚可以同看一页，但看见不等于取得替别人落字或改字的权力。',
      act_6_each_copy:'第六日五份抄本仍各归本人，桌上只有日期、经手数与物件种类三项问签；夜簿也只能沿用这种最小互见。',
      act_6_feed_one:'第六日的假封签由瓶儿保管撤回时辰、金莲只记接话者；夜簿若被拿去放线，也必须允许原落字者即时收回。',
    },[
      council7ChoiceText('council_7_tonight','只写今晚','每人亲写今晚一行；本人可留旧字更正，卯初全页失效','五个人在同一页各写本人今晚去处、是否留宿与可否转述，不准你或正堂代填。改口者亲手划旧字、添新时辰；门房只认最新一行，卯初后整页不再证明任何安排。'),
      council7ChoiceText('council_7_their_turn','各人写自己','五张本人签只处分本人答案；旁人不能排序，签条在今夜散席时失效','玉楼裁出五张本人签，谁愿意见、谁拒绝、谁暂不答，都由那个人自己写。月娘只编号码，金莲只核有没有替写；本人可随时收签或改签，今夜散席后旧签不能排成固定次序。'),
      council7ChoiceText('council_7_hide','不留去处副本','本人保留答案，门房只写转述责任；纠错仍由原说话人完成，卯初停止传递','五张本人答案仍留各院，门房只收一张不含院名的传话回执，记谁听见、谁送达、哪里被纠正。任何原话只能由说话者修改；卯初回执停止转递，也不能据“未写”猜成拒绝或应允。'),
    ]),
  follow_5_stop_rumor:council7HistoryVariant(
    'follow_5_stop_rumor','封门后只剩一角错送抄条','“春梅恃宠催汤”残条',
    '第五日门房收走了抄条，街面却仍把“春梅恃宠催汤”传成真话；如今桌上只有一角写着“灶上错送”的残纸。瓶儿把食盒油印从残角下抽开，雪娥要求先写清传错话不能扣谁的工，玉楼把两张相反的催菜单并排放下。若今晚仍封门，至少要决定谁能留下原话、谁能纠错，以及沉默到何时不再被管事借作加活。',{
      act_6_show_all:'第六日五处改字虽已共同摊开，门外仍没有第五日的修订本；今晚留下的任何共页都必须说明只在宅内有效。',
      act_6_each_copy:'第六日五份抄本各守院门，彼此只交换窄签；今晚若不留去处副本，也要给传错话留下可核的经手页。',
      act_6_feed_one:'第六日假封签已经主动出门，封门不再等于消息没有流动；瓶儿的撤回时辰与金莲记下的接话人必须留在责任页上。',
    },[
      council7ChoiceText('council_7_tonight','只写今晚','只在宅内写今晚去处与由此添的饭食；本人能改，门房不得外抄，卯初原页失效','五个人各自在宅内夜簿写一行今晚去处、是否留宿、饭食与能否转述。只有本人可划改，门房不得外抄；月娘在封面写明卯初作废，旧页既不能续排明夜，也不能拿去补第五日的街面宠次。'),
      council7ChoiceText('council_7_their_turn','各人写自己','本人答案各自封存，只交是否需要传话；本人收回即失效，散席全部作废','五个人各写自己的需要、拒绝与可转述范围，签条留在本人手里；门房只收“需传”或“不传”，不见院名内情。本人收回时该条立即失效，其余签也在今夜散席后全部作废。'),
      council7ChoiceText('council_7_hide','不留去处副本','不写院名，只具名传话错误与补救；本人改原话，责任页卯初封存','你不准门房抄任何去处，却让传话人逐个署名：听见什么、送到哪里、谁要求纠正。原话仍由本人保管和修改；卯初以后停止一切去处转述，责任页只保留错话由谁传、怎样补救。'),
    ]),
});

