export const ACT_TRANSITION_AFTERMATHS = Object.freeze({
  act_6_show_all: actAftermath('pan_jinlian',
    actAftermathBeat('li_pinger','瓶儿把五处改字的纸纤与封签一张张对齐','瓶儿没有继续争谁先受害。她把五处纸边压到同一盏灯下，发现每张都混着药铺旧封签的蓝纤，却故意只在指向她的那张露出完整药号。五份嫌疑并非五条线，而是一只手拆开的同一份货路。'),
    actAftermathBeat('wu_yueniang','月娘立下下一幕第一条交叉查账的规矩','月娘让每个人保存自己的原件，却规定任何指向某院的新证都必须先由另一院核日期、再由第三院核实物。玉楼负责经手名，雪娥负责真正动过的物件；从明日起，谁想用一份只够自证清白的纸拆院门，至少要骗过三个人。')),
  act_6_each_copy: actAftermath('wu_yueniang',
    actAftermathBeat('pan_jinlian','金莲拿不到别院抄本，只能从一句漏口听出矛盾','金莲问瓶儿那份写的是封签还是货单，瓶儿按先前约定拒绝展示。她又问雪娥纸上是油灰还是米灰，也只得到一句“与灶有关”。隐私守住了，可两份互相冲突的陷阱仍各自像真话，谁也没有足够资格指出。'),
    actAftermathBeat('meng_yulou','玉楼补了一套不交原文也能互相核对的问签','玉楼裁出五色窄签，只准写日期、经手人数和物件种类，不抄私话。五院每晚交换问签，若两份摘要相撞才由本人决定是否开原件。她保住了各自的门，却也承认这套办法慢一拍，敌人会得到更长的试探时间。')),
  act_6_feed_one: actAftermath('li_pinger',
    actAftermathBeat('sun_xuee','雪娥先问诱饵会不会拿下人当作第二层假证','雪娥把准备放出的假货单翻到背面，指出上头若留真实抬货人的手印，对手只要抓住一个下人，假嫌疑便会变成真口供。瓶儿于是换成无人领用的旧封签，明确不拿替她办事的人抵这枚饵。'),
    actAftermathBeat('pan_jinlian','金莲等到第一个接话的人，也把瓶儿的撤回权写在前面','消息放出不到半日，祝家外柜便派人问那批药是不是从瓶儿私院走的。金莲记下问法，却没有顺势把她说成真嫌疑；月娘规定只要瓶儿叫停，五院必须同时收饵。楔子骗来了一只手，也让另外三院看清这场险是怎样分担的。')),
  act_11_swap_read: actAftermath('wu_yueniang',
    actAftermathBeat('sun_xuee','雪娥从月娘那份里看见被删掉的不是银数，而是做事的人','写月娘夺权的那页把所有挑水、守门和换封签的人并成“正堂使唤”。雪娥逐项补回原人，才发现造假者不只想让五院互疑，还在抹掉能证明证物流向的劳动。她补的名字恰与瓶儿读到的货路对上。'),
    actAftermathBeat('pan_jinlian','金莲把五份互斥真相钉成一条会自相揭穿的证链','金莲让每个人只念别人那份里自己亲眼见过的一句，再把五句按时辰排开。玉楼的名帖不可能同时出现在两个城门，雪娥的米斗也不可能先失后入；五张纸第一次不靠相信谁，而靠彼此无法同时成立来拆穿。')),
  act_11_verify_first: actAftermath('li_pinger',
    actAftermathBeat('meng_yulou','玉楼发现五份各自验真的结果仍缺一张共同索引','瓶儿证明封签为假，雪娥证明米数被改，月娘证明日期错位，五个人都洗清了自己，却仍不知道那些假处是不是出自同一手。玉楼说，各自有答案不等于宅里有答案；如果证物不相见，对手下回仍能换一种分法。'),
    actAftermathBeat('wu_yueniang','月娘只合并核验结论，不强收五院原件','月娘另开一册，只写“何日、何物、由谁验过、与哪条结论冲突”，原口供仍留各院。金莲嫌这办法不够快，瓶儿却同意先把可共享的硬证连起来。五院没有完全互开，却从此能看见孤立真相之间有没有同一只手。')),
  act_11_return_marked: actAftermath('pan_jinlian',
    actAftermathBeat('meng_yulou','玉楼按五种纸线追出假本被收走的不同次序','第一份在药铺后门消失，第二份被送进祝家茶房，第三份却绕回宅外的抄书铺。玉楼没有叫人立刻拦截，而把每次接手与纸线颜色对上；对方以为五院仍各信一份，实际已经替她们画出一张收话人的路。'),
    actAftermathBeat('li_pinger','瓶儿发现一枚真封签也被试着撬开，反套并非没有代价','第三夜，一张带蓝线的假本回来时夹着瓶儿真货路上的蜡屑。她立刻换锁，并要求金莲删掉所有会指向活人的诱句。五个人抓到传递次序，却也暴露了她们开始互通；下一幕能反追外柜，前提是没人把危险当成只属于瓶儿。')),
  act_16_refuse_name: actAftermath('wu_yueniang',
    actAftermathBeat('li_pinger','瓶儿接到外柜撤回单人优待后的第一张停货票','五个名字都不交以后，外柜立即冻结一条药材赊线，显然要证明拒绝偏爱会有真价。瓶儿没有拿私银替全宅遮住，只报出能撑三日的存货与不能动的退路；谁要继续硬顶，必须先承认这笔损失落在哪里。'),
    actAftermathBeat('sun_xuee','雪娥把拒绝牺牲一院改成五份具体承担','雪娥先扣下三日粮，再让月娘、金莲、瓶儿、玉楼各写自己能接的一项：官面答话、辨伪、调货、借名。她只接仓灶与实物，不替任何人多背一句。五个名字没有被卖出，也没有被一句漂亮的“共同承担”重新抹平。')),
  act_16_buy_all_names: actAftermath('li_pinger',
    actAftermathBeat('sun_xuee','雪娥把赎名后的空银匣搬到桌上，不准只庆幸纸回来了','五张纸取回，现银也少了一大截。雪娥当面划去三项宴席用度，保住米、药与守门工钱；她问谁若把赎名当作你的恩情，就先解释少掉的这顿饭由谁来填。五个人收回名字，也一同看见了赎回的真实成本。'),
    actAftermathBeat('wu_yueniang','月娘与瓶儿把六十五两写成可追问的共同支出','瓶儿列清付款来路与补银期限，月娘注明这笔钱买回的是五份追索纸，不买任何人的顺从。玉楼负责追回一笔外欠，金莲查纸是否另有副本；赎名从一次豪掷变成了五个人都能查账、也能质疑的共同决定。')),
  act_16_sign_your_name: actAftermath('pan_jinlian',
    actAftermathBeat('wu_yueniang','月娘先挡住外柜把你的签名解释成替五院总保','外柜掌事说既然你愿担责，五院证物便都可并进你的名下。月娘当场划开两栏：你的名字只承认拒绝优待和接受追索，不取得任何一院的证词、私产或撤回权。金莲逐字念给门外的人听，不许一句含糊过去。'),
      actAftermathBeat('meng_yulou','玉楼让这份额外签名越过院门，却不把它写成英雄故事','玉楼借来见证名帖，只证明你亲手拒绝了五选一，没有替你夸成救下五院。瓶儿、雪娥各收自己的副本，金莲保留追问；门外债务并未因此清零，门内却留下一个可核的事实：你的风险不能兑换她们的名字。')),
});

