const externalActor = (id, name, role) => Object.freeze({ id, name, role });
export const EXTERNAL_REBUTTAL_ACTORS = Object.freeze([
  externalActor('dai_an','玳安','只认亲见门路的有限证人'),
  externalActor('han_daoguo','韩道国','抓一处页缝反咬整本账的经手人'),
  externalActor('ying_bojue','应伯爵','把程序争议改讲成私德笑话的传话人'),
]);

const externalVoice = (actor, line) => Object.freeze({ actor, line });
const externalRebuttalChoice = (id, label, hint, resultTitle, speaker, text, day17Echo, finalEcho, effects) => Object.freeze({
  ...route(id, label, hint, text, effects), resultTitle, speaker, day17Echo, finalEcho,
});
const externalRebuttal = (id, label, title, body, question, voices, choices) => Object.freeze({
  id, day:16, label, title, body, question,
  actors:EXTERNAL_REBUTTAL_ACTORS,
  voices:Object.freeze(voices),
  choices:Object.freeze(choices),
});

// 第十五日证链不是一次性的胜负标签。第十六日的单人优待刚处理完，
// 三名外部人物便把“有限证言→账页异议→门外版本”接成一轮复案。
// 玩家第二次选择守住的是程序、证人边界或舆论先手，三者不能同时拿走。
export const EXTERNAL_REBUTTALS = Object.freeze({
  complete:externalRebuttal(
    'external_rebuttal_complete','闭链复问','证链没散，应伯爵便来争谁有资格解释它',
    '三份证物仍能逐段复查，门外却换了问法：既然每一段都站得住，便攻击五个人为何能把它们排成同一条线。真伪之争变成了谁在幕后教她们说话。',
    '闭链能挡住事实反问，却不会自动赢得门外版本。你现在只能选一条战线先守。',[
      externalVoice('dai_an','“小的只认申时二刻送到角门，也认韩伙计在门里。袖里是哪一本，小的不曾看见。”'),
      externalVoice('han_daoguo','“门簿既不认袖中物，我只圈这一页新墨。诸位若说整本都真，先别拿别页替这一页作保。”'),
      externalVoice('ying_bojue','“一位不敢认内容，一位仍圈着异议；五院却恰好一人接一句，倒像早练过的。”'),
    ],[
      externalRebuttalChoice('external_complete_segment','把反问各归一段','可守住闭链；三个人只能为自己真正质疑的部分负责','三句反问被钉回三个范围','wu_yueniang','月娘另开三栏：玳安只签时辰与路线，韩道国必须把异议钉在一页，应伯爵则在原听众前复述哪一句是事实、哪一句只是他的推断。金莲逐栏追问，瓶儿与雪娥把原物留在桌上。三种反问仍在，却再不能互相借力冒充整案崩塌。','第十七日夜查柜坊时，韩道国只能追问已经圈出的那一页，不能借一处新墨重开整本账。','第十六日复案把三种反问各自钉回范围，门外再不能用一句“都可疑”吞掉整条证链。',{house:3,power:1,exposure:2,strain:2,flags:['external_complete_segmented'],bonds:[['wu_yueniang','li_pinger',2],['meng_yulou','sun_xuee',2],['pan_jinlian','meng_yulou',1]],relAll:Object.fromEntries(HEROINE_IDS.map(id=>[id,{qing:1,du:-1}]))}),
      externalRebuttalChoice('external_complete_limited','只保有限证言','主动撤掉对玳安未亲见部分的借用，闭链仍保留其余两段','玳安的“不知道”保住了证言','meng_yulou','玉楼先划去所有“玳安见到账本”的转述，只留下他亲自跑过的时辰与角门。月娘把缺掉的内容证据重新归到账页和实物，不逼一个小厮替整条链背书。官面少了一分便利，证人却不必靠越界才显得有用。','第十七日院议会记住：允许追问不等于逼人补认未亲见的内容，拒答本身不能被写成翻供。','第十六日主动缩回过度转述，玳安的有限证言因此没有在终局被反咬成一次翻供。',{house:2,power:-1,exposure:-3,strain:1,flags:['external_complete_limited'],bonds:[['meng_yulou','sun_xuee',3],['wu_yueniang','li_pinger',-2],['pan_jinlian','meng_yulou',1]],relAll:{meng_yulou:{qing:2,du:-2},sun_xuee:{qing:2,du:-2},wu_yueniang:{du:1},li_pinger:{du:1}}}),
      externalRebuttalChoice('external_complete_street','让短帖先出门','只公开假息、改账与诱供；抢先手，也把删改权暂交给应伯爵','短帖先赢了街口，原卷仍留在五院','pan_jinlian','金莲写下一张只含假息、改账与诱供的短帖，不抄五院私话；玉楼逼应伯爵在原听众前照字念完。街口先听见了可核的三件事，却也开始追问被删去的部分。你赢下一日口风，没有因此让任何一页账变得更真。','第十七日院议必须处理一个新风险：公开问话里的“不答”，会不会又被短帖剪成默认承认。','第十六日短帖抢先占住街口，终局时外柜先攻的是短帖与原卷是否一致，而不是账上有没有假息。',{house:-3,power:2,repute:1,exposure:7,strain:2,flags:['external_complete_street'],bonds:[['pan_jinlian','meng_yulou',3],['wu_yueniang','li_pinger',-2],['meng_yulou','sun_xuee',-2]],relAll:{pan_jinlian:{qing:2},meng_yulou:{qing:2},wu_yueniang:{du:2},li_pinger:{du:3},sun_xuee:{du:3}}}),
    ]),
  rebuttable:externalRebuttal(
    'external_rebuttal_rebuttable','留缝复核','韩道国把一处承接空白举成了整本账的裂口',
    '公审已经成案，却有一份证物递得太早。韩道国不必否认米斗、门簿或原账，只要要求那处空白重验；应伯爵已经把“尚待复核”讲成“五院自己也说不清”。',
    '你能补这一缝、保住有限证言，或抢先说明正在复核；任何一种都必须承认原案并非无缝。',[
      externalVoice('dai_an','“小的认自己跑过的时辰。堂上若把没见过的那一截也记在小的名下，小的今日便得划掉。”'),
      externalVoice('han_daoguo','“我只问这一处怎样从前证接到后证。若接不上，总不能拿三张真纸逼人认同一个结论。”'),
      externalVoice('ying_bojue','“堂上说待复核，街上听见的便是还没说清。五院若各补一句，谁知补的是证还是口径？”'),
    ],[
      externalRebuttalChoice('external_rebuttable_segment','把反问各归一段','可补这一缝；重验一处，不准韩道国重开整本','留缝被公开补成了一段新承接','li_pinger','瓶儿先把争议页单独封起，雪娥重称实物，玉楼核门路，金莲只对照这一页前后的改词。韩道国得到一次真正的重验，却不能再把别页拖进来；月娘把“原案留缝、今日补证”并列记录，没有偷偷把第一次公审改写成从未出错。','第十七日柜坊封痕成为补证而非另起炉灶；韩道国只能质疑这次明确圈出的承接处。','第十六日公开承认并补上原案留缝，终局能够区分第一次公审与后来的复核，不再假装证链天生完整。',{house:3,power:1,exposure:3,strain:2,flags:['external_rebuttable_segmented'],bonds:[['wu_yueniang','li_pinger',2],['meng_yulou','sun_xuee',2],['pan_jinlian','meng_yulou',1]],relAll:Object.fromEntries(HEROINE_IDS.map(id=>[id,{qing:1,du:-1}]))}),
      externalRebuttalChoice('external_rebuttable_limited','只保有限证言','承认尚不能证明完整经手；保门路、原工簿与原账页','缺口留下了，证人没有被逼成万能钥匙','sun_xuee','雪娥把“今日不能证明”写在最上面，只保米斗、原工簿、原账页与玳安亲见的门路。玉楼拒绝替空白时辰借名，瓶儿也不拿封签补自己没有经手的一刻。外案仍留着窄缝，五院却第一次把证据不足说成事实，而不是谁不肯尽忠。','第十七日若拓下七号柜格旧封痕，便能另添硬证；即使失手，玳安也不再被写成翻供者。','第十六日保住了有限证言，终局仍有缺口，却不能再用“玳安翻供”抹掉他确实看见的门路。',{house:2,power:-1,exposure:-3,strain:1,flags:['external_rebuttable_limited'],bonds:[['meng_yulou','sun_xuee',3],['wu_yueniang','li_pinger',-2],['pan_jinlian','meng_yulou',1]],relAll:{meng_yulou:{qing:2,du:-2},sun_xuee:{qing:2,du:-2},wu_yueniang:{du:1},li_pinger:{du:1}}}),
      externalRebuttalChoice('external_rebuttable_street','让短帖先出门','公开“哪一段待复核”，不把留缝说成已经补好','街口先知道缺口在哪，也先学会盯着它问','meng_yulou','玉楼让短帖只写三件已证事实与一处待复核，不删“待”字。应伯爵照念以后，街口不再能笼统说五院全假，却把那一处空白盯得更紧。你争回了问题的形状，也把下一次失手的代价公开放大。','第十七日院议必须决定谁能复述公开问答；五份私答会让唯一缺口裂成五种版本。','第十六日短帖没有假装留缝已补，终局因此只需回答一处公开问题，也必须承担那一处被所有人看见。',{house:-3,power:2,repute:1,exposure:7,strain:2,flags:['external_rebuttable_street'],bonds:[['pan_jinlian','meng_yulou',3],['wu_yueniang','li_pinger',-2],['meng_yulou','sun_xuee',-2]],relAll:{pan_jinlian:{qing:2},meng_yulou:{qing:2},wu_yueniang:{du:2},li_pinger:{du:3},sun_xuee:{du:3}}}),
    ]),
  broken:externalRebuttal(
    'external_rebuttal_broken','断链重开','玳安拒绝越界，门外便把诚实讲成当堂翻供',
    '三份真证没有接成一条链。韩道国要求玳安补认袖中账本，应伯爵则把他的拒绝讲成“证人临阵改口”。你不能靠第二场漂亮问话把原案洗成闭链，只能决定抢回哪一段可信事实。',
    '这一局没有“补一笔便全好”的选项。重开程序、保窄证或公开承认断链，都会留下真实代价。',[
      externalVoice('dai_an','“小的只认申时二刻送到角门，也认韩伙计在门里。袖里是哪一本，小的不曾看见，不能替谁补。”'),
      externalVoice('han_daoguo','“既不曾看见，门路与流水之间便是空的。总不能拿一斗米替两页账作证，请先别把结论写满。”'),
      externalVoice('ying_bojue','“一位不敢认，一位说账有空，西门宅倒先把它叫成铁案了。外头的人可只会记得这句。”'),
    ],[
      externalRebuttalChoice('external_broken_reopen','撤原判，重开三段','只能重开，不能洗成闭链；原案的错误继续留在总账','原判没有被涂掉，新复核从第一段重开','wu_yueniang','月娘在原案旁写下“未闭合”，没有撕页。雪娥重新以米斗定事实，瓶儿与玉楼只接各自能证明的经手，金莲把口供留到最后却不宣称今日已经结案。韩道国取得逐段反问权，应伯爵也看见五院主动撤回了过度结论；你抢回程序，没有抢回一场并不存在的胜诉。','第十七日柜坊封痕只是新复核的第二块硬证，不会把第十五日原案偷偷改成闭链。','第十六日撤回了过度结论，终局面对的是一场仍在复核的新案，而不是拿假胜诉去撞第二次反问。',{house:2,power:-1,exposure:2,strain:3,flags:['external_broken_reopened'],bonds:[['wu_yueniang','li_pinger',2],['meng_yulou','sun_xuee',2],['pan_jinlian','meng_yulou',1]],relAll:Object.fromEntries(HEROINE_IDS.map(id=>[id,{qing:1,du:-1}]))}),
      externalRebuttalChoice('external_broken_limited','只保有限证言','撤掉袖中物与动机推断，只保玳安亲见门路和各自原件','断链仍在，最窄的证言被保了下来','meng_yulou','玉楼划掉所有要求玳安证明袖中物的句子，只让他认门、时辰与亲见之人。雪娥保自己的米斗，瓶儿保原账，金莲暂不再用改口推结论。原案缩成几段尚未相接的真事，官势受损，却没人再能把一个小厮的诚实拒答叫作翻供。','第十七日可以借柜坊封痕另起硬证；无论成败，玳安的“不知道”已被正式写成证言边界。','第十六日主动缩窄断链，终局仍不能声称完整经手，却保住了几段不依赖逼供的可信事实。',{house:2,power:-1,exposure:-3,strain:1,flags:['external_broken_limited'],bonds:[['meng_yulou','sun_xuee',3],['wu_yueniang','li_pinger',-2],['pan_jinlian','meng_yulou',1]],relAll:{meng_yulou:{qing:2,du:-2},sun_xuee:{qing:2,du:-2},wu_yueniang:{du:1},li_pinger:{du:1}}}),
      externalRebuttalChoice('external_broken_street','公开承认三纸断链','短帖只说哪些纸是真的、为何尚不能推出同一结论','门外先听见了失败，也看见谁没有逼证人圆话','pan_jinlian','金莲亲手在短帖首行写“三纸未成链”，再分列米斗、账页与门路各自能证明什么。应伯爵拿走的是一份承认失败的公开说明，无法替五院造出胜诉，却也很难再把她们说成偷偷串词。街口知道得更多，宅里则要承受所有人围着缺口发问。','第十七日院议里的“不答”会被门外逐句盯住；若把五份问答重新拆回私门，街口只会剩应伯爵那一版。','第十六日先公开承认断链，终局没有虚假的铁案可守，却保住了哪些事实仍真、哪些结论从未成立的分界。',{house:-3,power:1,repute:1,exposure:7,strain:2,flags:['external_broken_street'],bonds:[['pan_jinlian','meng_yulou',3],['wu_yueniang','li_pinger',-2],['meng_yulou','sun_xuee',-2]],relAll:{pan_jinlian:{qing:2},meng_yulou:{qing:2},wu_yueniang:{du:2},li_pinger:{du:3},sun_xuee:{du:3}}}),
    ]),
});

