const personalDepartureProcedureSet = (procedureId, owner, procedure) => Object.freeze(Object.fromEntries(
  HEROINE_IDS.filter((heroineId) => heroineId !== owner).map((heroineId) => {
    const heroine = HEROINES[heroineId];
    const voice = personalDepartureProcedureVoices[procedureId][heroineId];
    const reply = (outcome) => personalDepartureReply(
      `${heroine.short}：${procedure[outcome].title}`,
      `${procedure[outcome].line}${voice[outcome]}`,
    );
    return [heroineId, personalDepartureSet(reply('accept'), reply('amend'), reply('refuse'))];
  }),
));

