const crisisStructureCard = (id,label,hint,participants,fullText,boundedText,fullEffects,boundedEffects) => Object.freeze({
  id,label,hint,
  participants:Object.freeze(participants),
  fullText,boundedText,
  effectsByScope:Object.freeze({ full:fullEffects, bounded:Object.freeze(boundedEffects) }),
});

// 结构卡命名制度而非人物归顺。full 完整沿用既有 pairEffects；bounded 仍能止血，
// 但只开放较窄的物件、时限或证明范围，且九张卡各有不同资源后果。
