const routeStakeReturn = (returnText, observerText, question, keep, rewrite, deny) => Object.freeze({
  returnText,
  observerText,
  question,
  results:Object.freeze({ keep, rewrite, deny }),
});
const routeStakeReturns = (publicReturn, directReturn, privateReturn) => Object.freeze({
  public:publicReturn,
  direct:directReturn,
  private:privateReturn,
});

