const milestoneBeat = (speaker, text) => Object.freeze({
  speaker,
  text: typeof text === 'string' ? text : Object.freeze(text),
});
const milestoneChapter = (id, step, observer, asset, title, body, beats) => Object.freeze({
  id, step, observer, asset, title, body, milestone: true, beats: Object.freeze(beats),
});

// 第三次与第六次进同一扇门，进入人物关键章。它们不按日历幕复用，
