const invitationAftermathChoice = (id, label, hint, title, body, effects, witnessRel = {}, pairBond = 0) => Object.freeze({
  id, label, hint, title, body, effects: Object.freeze(effects), witnessRel: Object.freeze(witnessRel), pairBond,
});
const invitationAftermath = (witnessTitle, witnessBody, questionTitle, questionBody, choices) => Object.freeze({
  beats: Object.freeze([
    Object.freeze({ speaker:'witness', title:witnessTitle, body:witnessBody }),
    Object.freeze({ speaker:'heroine', title:questionTitle, body:questionBody }),
  ]),
  choices: Object.freeze(choices),
});

