      direct: '你让雪娥与{visited}直接找来领炭签。她们查出下人为了讨好两院擅自多开一炉，也共同定下以后任何临时夜火都须由受益院门署名。',
      hide: '你说昨夜的火由自己私下补，不许再拿到廊下讲。雪娥把欠工签贴到门房簿上：“既然门内不认，便让门外人人看是谁还没拿到银。”',
