  li_pinger: '瓶儿把钥匙仍留在腕上：“我可以说昨夜哪一笔与我有关，门里的细处不拿来换太平。你要问他，就让他站在这里自己答。”',
  meng_yulou: '玉楼没有笑着打圆场：“我愿认下昨夜收过的情，也愿还该还的人情。官人留下的空白，今日别再叫我替他写得体面。”',
