      '门房簿明写你昨夜从亮处离开角门。金莲没有补暧昧话，也没人能拿藏身二字卖新闲话。',
      '堂前口供末尾仍留着“够了”。有人笑她欲擒故纵时，你先把这两个字原样认回自己名下。',
